CREATE TABLE IF NOT EXISTS `audit_event` (`id` BIGINT NOT NULL AUTO_INCREMENT, `event_id` CHAR(32) NOT NULL, `schema_version` SMALLINT UNSIGNED NOT NULL DEFAULT 1, `occurred_at` BIGINT NOT NULL, `actor_type` ENUM('user', 'system') NOT NULL, `actor_id` VARCHAR(128) NOT NULL, `tenant_id` BIGINT NULL, `action` VARCHAR(128) NOT NULL, `subject_type` VARCHAR(64) NULL, `subject_id` VARCHAR(128) NULL, `target_type` VARCHAR(64) NOT NULL, `target_id` VARCHAR(128) NOT NULL, `before_summary` JSON NULL, `after_summary` JSON NULL, `request_id` CHAR(32) NOT NULL, `result` ENUM('succeeded', 'denied', 'failed') NOT NULL, PRIMARY KEY (`id`), UNIQUE KEY `uk_audit_event_event_id` (`event_id`), KEY `idx_audit_event_actor` (`actor_type`, `actor_id`, `occurred_at`, `id`), KEY `idx_audit_event_subject` (`subject_type`, `subject_id`, `occurred_at`, `id`), KEY `idx_audit_event_target` (`target_type`, `target_id`, `occurred_at`, `id`), KEY `idx_audit_event_tenant` (`tenant_id`, `occurred_at`, `id`), KEY `idx_audit_event_request` (`request_id`, `id`), KEY `idx_audit_event_retention` (`occurred_at`, `id`), CONSTRAINT `chk_audit_event_event_id` CHECK (`event_id` COLLATE utf8mb4_bin REGEXP '^[0-9a-f]{32}$'), CONSTRAINT `chk_audit_event_request_id` CHECK (`request_id` COLLATE utf8mb4_bin REGEXP '^[0-9a-f]{32}$'), CONSTRAINT `chk_audit_event_subject_pair` CHECK ((`subject_type` IS NULL AND `subject_id` IS NULL) OR (`subject_type` IS NOT NULL AND `subject_id` IS NOT NULL)), CONSTRAINT `chk_audit_event_tenant_id` CHECK (`tenant_id` IS NULL OR `tenant_id` > 0)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
